import numpy as np
import pandas as pd

train = pd.read_csv('train.csv')
X = train.drop(columns=['target']).to_numpy(float)
y = train['target'].to_numpy(float)

n = len(y)
idx = np.arange(n)
folds = [idx[i::5] for i in range(5)]

def rmse(a,b):
    return float(np.sqrt(np.mean((a-b)**2)))

def add_bias(X):
    return np.c_[np.ones(len(X)), X]

def fit_ols(Xtr, ytr):
    return np.linalg.pinv(add_bias(Xtr)) @ ytr

def pred_lin(beta, Xte):
    return add_bias(Xte) @ beta

def fit_ridge(Xtr, ytr, alpha):
    Xb = add_bias(Xtr)
    I = np.eye(Xb.shape[1])
    I[0,0] = 0.0
    return np.linalg.solve(Xb.T @ Xb + alpha * I, Xb.T @ ytr)

def pred_knn(Xtr, ytr, Xte, k):
    out = []
    for x in Xte:
        d = np.sqrt(((Xtr - x)**2).sum(axis=1))
        nn = np.argpartition(d, k-1)[:k]
        w = 1.0 / (d[nn] + 1e-6)
        out.append(np.dot(w, ytr[nn]) / w.sum())
    return np.array(out)

models = []
for name in ['ols']:
    preds = np.empty(n)
    for fold in folds:
        tr = np.setdiff1d(idx, fold)
        beta = fit_ols(X[tr], y[tr])
        preds[fold] = pred_lin(beta, X[fold])
    models.append((name, rmse(y, preds)))
for alpha in [1e-4,1e-3,1e-2,1e-1,1,10,100]:
    preds = np.empty(n)
    for fold in folds:
        tr = np.setdiff1d(idx, fold)
        beta = fit_ridge(X[tr], y[tr], alpha)
        preds[fold] = pred_lin(beta, X[fold])
    models.append((f'ridge_{alpha:g}', rmse(y, preds)))
for k in [1,2,3,5,8,10]:
    preds = np.empty(n)
    for fold in folds:
        tr = np.setdiff1d(idx, fold)
        preds[fold] = pred_knn(X[tr], y[tr], X[fold], k)
    models.append((f'knn_{k}', rmse(y, preds)))
for name, score in sorted(models, key=lambda x: x[1]):
    print(name, f'{score:.6f}')
